message.content:
{
"events": [
{
"key": "hsr_scattered_banknotes",
"story": "황금의 순간 속 머니 머신에서 쏟아진 지폐들이 사방으로 흩어집니다. 어벤츄린은 돈이 나오는 것과 쫓아가서 챙기는 것은 별개의 문제라며 당신에게 판돈을 묻습니다. 당신은 작은 판돈을 걸고 멀리 흩어진 지폐를 쫓거나 눈앞의 몫만 챙겨야 합니다.",
"intro": "어벤츄린이 여유로운 미소를 지으며 당신을 바라봅니다.",
"choices": [
{
"label": "200골드를 걸고 흩어진 지폐 끝까지 따라간다",
"result": "당신은 수입과 치명타 피해를 늘리는 대신 이동이 느려지는 성장을 얻었습니다. 260골드를 획득했습니다. 어벤츄린은 당신의 선택이 꽤나 짜릿했다고 덧붙입니다."
},
{
"label": "어벤츄린과 위험이 늘어날 길까지 계산한다",
"result": "당신은 치명타 확률과 치명타 피해를 높이는 요령을 익혔습니다. 적의 강도가 한 단계 높아졌습니다. 어벤츄린은 당신의 계산 능력을 높게 평가하며 눈을 가늘게 뜹니다."
},
{
"label": "눈앞에서 받은 몫만 챙긴다",
"result": "당신은 눈앞에 떨어진 몫을 챙겨 180골드를 얻었습니다. 어벤츄린은 당신의 신중함을 보며 고개를 끄덕입니다."
}
]
},
{
"key": "hsr_floating_treat",
"story": "꿈속 황금의 순간에서 아이스크림을 잡으려 할 때마다 바로 앞의 빈 자리가 눈에 들어옵니다. 미샤는 다른 별에서도 이런 간식을 먹는지 묻다가 당신이 내디딘 발을 발견합니다. 당신은 급히 손을 뻗을지 발을 둘 자리부터 살필지 정해야 합니다.",
"intro": "미샤가 호기심 가득한 눈빛으로 당신을 빤히 바라봅니다.",
"choices": [
{
"label": "미샤와 발을 둘 자리부터 보고 손을 뻗는다",
"result": "당신은 좋은 몸 상태에서 일격을 고르는 요령을 익혔습니다. 적의 수가 한 명 늘어났습니다. 미샤는 당신의 조심스러운 움직임을 보고 작게 미소 짓습니다."
},
{
"label": "150골드로 다른 간식을 고르고 여행 이야기를 들려준다",
"result": "당신은 150골드를 지불하고 작은 적을 처리하는 요령을 얻었습니다. 미샤는 당신의 여행 이야기에 귀를 기울이며 즐거워합니다."
},
{
"label": "이 간식은 내려놓고 다른 주문의 전달을 돕는다",
"result": "당신은 100골드와 물약 1개를 받았습니다. 미샤는 당신의 친절함에 고마움을 표하며 물러납니다."
}
]
},
{
"key": "hsr_dream_eye_gap",
"story": "꿈 건축 경계의 막힌 입구에서 건축가는 꿈의 눈으로 보이는 도면만 보여줍니다. 아케론은 장검을 든 채 그림의 연결 부분과 실제 발을 둘 간격이 같은지 묻습니다. 당신은 공사장 내부 대신 도면 밖의 통로에서 그 간격을 확인해야 합니다.",
"intro": "아케론이 무거운 분위기를 풍기며 당신 곁에 섭니다.",
"choices": [
{
"label": "아케론과 더 강한 적이 오가는 바깥 통로의 간격을 짚는다",
"result": "당신은 단단한 방어를 뚫을 일격의 방향을 고르는 요령을 익혔습니다. 적의 강도가 한 단계 높아졌습니다. 아케론은 당신의 분석에 짧게 고개를 끄덕입니다."
},
{
"label": "180골드로 도면 사본을 받아 다른 연결을 비교한다",
"result": "당신은 180골드를 지불하고 좋은 몸 상태에서 일격을 고르는 요령을 얻었습니다. 아케론은 당신이 도면을 꼼꼼히 살피는 것을 지켜봅니다."
},
{
"label": "막힌 입구에 들어가지 않고 자료 전달 보수를 받는다",
"result": "당신은 자료 전달 보수로 130골드를 받았습니다. 적의 수가 한 명 줄어들었습니다. 아케론은 아무 말 없이 당신의 뒤를 따릅니다."
}
]
},
{
"key": "hsr_scene_after_applause",
"story": "클락 스튜디오의 촬영 체험에서 끝났다는 표시 뒤에도 한 배우가 다른 역을 이어갑니다. 스파클은 지금 웃는 사람이 누구의 편인지 물으며 아직 남은 장면이 있다고 말합니다. 안내인은 당신에게 마칠 장면을 정해 달라고 요청합니다.",
"intro": "스파클이 장난기 가득한 표정으로 당신의 어깨에 손을 올립니다.",
"choices": [
{
"label": "150골드를 내고 스파클의 마지막 장면을 다시 맞춘다",
"result": "당신은 150골드를 지불하고 빠른 동작 뒤 일격에 힘을 싣는 요령을 얻었습니다. 스파클은 만족스러운 듯 크게 웃음을 터뜨립니다."
},
{
"label": "더 많은 적이 오가는 역할을 맡아 직접 장면을 이어 간다",
"result": "당신은 동작과 일격을 빠르게 이어 가는 요령을 익혔습니다. 적의 수가 두 명 늘어났습니다. 스파클은 당신의 열정에 박수를 보냅니다."
},
{
"label": "끝났다는 표시에서 멈추고 체험 보수를 받는다",
"result": "당신은 체험 보수로 160골드를 받았습니다. 스파클은 아쉬운 듯 입술을 내밀며 뒤로 물러납니다."
}
]
},
{
"key": "hsr_monster_last_order",
"story": "꿈세계 몬스터들을 위한 바에서 잔을 내민 손님이 단맛이 싫다고 뒤늦게 말합니다. 갤러거는 손님을 예의 있게 대하면서도 왜 처음에는 다른 주문을 했는지 다시 묻습니다. 당신은 새 잔을 마련할지 손님 말을 먼저 들을지 다른 주문을 맡을지 정해야 합니다.",
"intro": "갤러거가 곤란한 듯 미간을 찌푸리며 당신을 쳐다봅니다.",
"choices": [
{
"label": "200골드로 새 잔을 마련하고 갤러거와 손님 말을 먼저 듣는다",
"result": "당신은 200골드를 지불하고 몸 상태를 유지하며 피해를 줄이는 요령을 얻었습니다. 갤러거는 당신의 대처에 안도의 한숨을 내쉽니다."
},
{
"label": "더 많은 적을 맡는 대신 갤러거에게 버티는 요령을 배운다",
"result": "당신은 공격을 이어 가며 버틸 힘을 얻고 받는 피해를 줄이는 요령을 익혔습니다. 적의 수가 한 명 늘어났습니다. 갤러거는 고마운 듯 당신에게 눈인사를 건넵니다."
},
{
"label": "다른 주문만 전달하고 보수와 물약을 받는다",
"result": "당신은 100골드와 물약 1개를 받았습니다. 적의 수가 한 명 줄어들었습니다. 갤러거는 당신의 효율적인 처리에 고개를 끄덕입니다."
}
]
},
{
"key": "hsr_jade_unwritten_price",
"story": "제이드는 네가 골라 온 물건보다 그것을 고른 이유를 오래 듣습니다. 너는 골드만 내면 끝나는 거래인지 묻지만 제이드는 더 큰 수입을 고르면 앞으로의 움직임도 무거워질 수 있다고 합니다. 값과 남을 부담을 모두 읽고 거래할지 지금 가진 몫으로 돌아갈지 정합니다.",
"intro": "제이드가 차분한 목소리로 당신의 눈을 응시합니다.",
"choices": [
{
"label": "230골드와 느려질 이동을 받아들이고 거래한다",
"result": "당신은 230골드를 지불하고 피해와 수입을 늘리는 대신 이동이 느려지는 성장을 얻었습니다. 제이드는 만족스러운 듯 거래를 마무리합니다."
},
{
"label": "거래 대신 더 강한 적이 있는 쪽을 택하고 회피할 동선을 익힌다",
"result": "당신은 동작을 빨리 이어 가며 작은 적을 처리하는 요령을 익혔습니다. 적의 강도가 한 단계 높아졌습니다. 제이드는 당신의 결단력을 높게 평가합니다."
},
{
"label": "거래를 맺지 않고 서류 전달의 보수만 받는다",
"result": "당신은 서류 전달 보수로 140골드를 받았습니다. 제이드는 아쉬운 듯 미소를 지으며 당신을 배웅합니다."
}
]
}
]
}
